//! Audit assertions of current loss/boundary behaviour, not fixes.
use serde_json::{json,Value};
use vowl_wasm::{ontology::{OntologyParser,parser::{StandardParser,ParserConfig}},graph::{builder::GraphBuilder,node::NodeBuilder,edge::EdgeBuilder,statistics::GraphStatistics,EdgeType,VowlGraph},render::{Renderer,SvgRenderer}};
fn fixture()->Value {json!({"class":[{"id":"a","label":"A"},{"id":"b","label":"B"}],"property":[{"id":"p","domain":"a","range":"b"}]})}
#[test] fn iri_validation_flag_does_not_validate_iris(){let mut j=fixture();j["class"][0]["iri"]=json!("not an IRI with spaces");let p=StandardParser::new();let d=p.parse(&j.to_string()).unwrap();assert!(p.validate(&d).is_ok());assert!(GraphBuilder::from_ontology(&d).is_ok());}
#[test] fn separate_attribute_tables_are_not_joined(){let j=json!({"class":[{"id":"a","type":"owl:Class"}],"classAttribute":[{"id":"a","label":{"en":"Meaningful label"},"iri":"urn:meaningful"}],"property":[{"id":"p","type":"owl:ObjectProperty"}],"propertyAttribute":[{"id":"p","domain":"a","range":"a"}]});let p=StandardParser::new();assert!(p.parse(&j.to_string()).unwrap_err().to_string().contains("Missing domain"));let mut j=j;j["property"]=json!([]);let d=p.parse(&j.to_string()).unwrap();assert_eq!(d.classes[0].label,"a");assert_eq!(d.classes[0].iri,"a");}
#[test] fn parsed_equivalences_and_individuals_disappear_in_graph(){let mut j=fixture();j["class"][0]["equivalent"]=json!(["b"]);j["class"][0]["individuals"]=json!(7);let d=StandardParser::new().parse(&j.to_string()).unwrap();assert_eq!(d.classes[0].equivalent,vec!["b"]);assert_eq!(d.classes[0].attributes.individuals,Some(7));let g=GraphBuilder::from_ontology(&d).unwrap();let n=g.get_node("a").unwrap();assert!(n.semantic.equivalent.is_empty());assert_eq!(n.semantic.individuals,None);}
#[test] fn cardinality_limits_are_lost_or_narrowed(){let p=StandardParser::new();let mut j=fixture();j["property"][0]["minCardinality"]=json!(2);assert!(p.parse(&j.to_string()).unwrap().properties[0].characteristics.cardinality.is_none());j["property"][0]["cardinality"]=json!(3);j["property"][0].as_object_mut().unwrap().remove("minCardinality");let d=p.parse(&j.to_string()).unwrap();assert_eq!(d.properties[0].characteristics.cardinality.as_ref().unwrap().exact,Some(3));assert_eq!(GraphBuilder::from_ontology(&d).unwrap().edges()[0].characteristics.cardinality,Some((None,None)));j["property"][0]["cardinality"]=json!(4294967296u64);assert_eq!(p.parse(&j.to_string()).unwrap().properties[0].characteristics.cardinality.as_ref().unwrap().exact,Some(0));}
#[test] fn datatype_range_passes_validation_then_fails_build(){let mut j=fixture();j["property"][0]["range"]=json!("xsd:string");let p=StandardParser::new();let d=p.parse(&j.to_string()).unwrap();p.validate(&d).unwrap();assert!(GraphBuilder::from_ontology(&d).unwrap_err().to_string().contains("not found"));}
#[test] fn conventional_subclass_spelling_is_not_mapped(){let mut j=fixture();j["property"][0]["type"]=json!("rdfs:subClassOf");let d=StandardParser::new().parse(&j.to_string()).unwrap();let mut g=GraphBuilder::from_ontology(&d).unwrap();assert_eq!(g.edges()[0].edge_type,EdgeType::Special("rdfs:subClassOf".into()));g.apply_hierarchy_folding(0);assert!(g.nodes().iter().all(|n|n.visual.visible));}
#[test] fn explicit_inverse_pair_generates_duplicate_edges(){let mut j=fixture();j["property"]=json!([{"id":"p","domain":"a","range":"b","inverseOf":"q"},{"id":"q","domain":"b","range":"a","inverseOf":"p"}]);let d=StandardParser::new().parse(&j.to_string()).unwrap();let g=GraphBuilder::from_ontology(&d).unwrap();assert_eq!(g.edge_count(),4);assert_eq!(g.edges().iter().filter(|e|e.id=="p").count(),2);assert!(GraphStatistics::calculate(&g).basic.density>1.0);}
#[test] fn class_limit_silently_removes_nodes_but_keeps_properties(){let p=StandardParser::with_config(ParserConfig{max_classes:1,..Default::default()});let d=p.parse(&fixture().to_string()).unwrap();assert_eq!(d.classes.len(),1);assert_eq!(d.properties.len(),1);p.validate(&d).unwrap();assert!(GraphBuilder::from_ontology(&d).is_err());}
#[test] fn component_metrics_depend_on_insertion_order(){fn build(ids:[&str;2])->VowlGraph{let mut g=VowlGraph::new();for id in ids{g.add_node(NodeBuilder::new(id).build()).unwrap();}g.add_edge("b","a",EdgeBuilder::new("p").build()).unwrap();g}let a=GraphStatistics::calculate(&build(["a","b"]));let b=GraphStatistics::calculate(&build(["b","a"]));assert_eq!(a.components.num_components,2);assert_eq!(b.components.num_components,1);assert_eq!(a.components.isolated_nodes,2);}
#[test] fn svg_output_does_not_escape_filter_fit_or_draw_edges(){let mut g=VowlGraph::new();let mut n=NodeBuilder::new("a").label("<audit-node/>").position(10000.0,10000.0).build();n.visual.visible=false;g.add_node(n).unwrap();g.add_node(NodeBuilder::new("b").build()).unwrap();g.add_edge("a","b",EdgeBuilder::new("p").label("--> <audit-edge/> <!--").build()).unwrap();let svg=SvgRenderer::new(400.0,300.0).render(&g).unwrap();assert!(svg.contains("<audit-node/>"));assert!(svg.contains("<audit-edge/>"));assert!(svg.contains("10000"));assert!(!svg.contains("<line"));}
#[test] fn zero_debug_log_interval_panics(){let mut f=vowl_wasm::debug::DebugFlags::new();f.log_interval=0;assert!(std::panic::catch_unwind(|| f.should_log(0)).is_err());}
